var ta = new Int32Array(new SharedArrayBuffer(16));
ta[0] = 10;
var r1 = Atomics.sub(ta, 0, 3);
if (r1 !== 10 || ta[0] !== 7) throw new Error("int32: r1=" + r1 + " ta0=" + ta[0]);
var u8 = new Uint8Array(4);
u8[0] = 1;
var r2 = Atomics.sub(u8, 0, 2);
if (r2 !== 1 || u8[0] !== 255) throw new Error("uint8 wrap: r2=" + r2 + " u8=" + u8[0]);
var b = new BigInt64Array(new SharedArrayBuffer(16));
b[0] = 5n;
var r3 = Atomics.sub(b, 0, 8n);
if (r3 !== 5n || b[0] !== -3n) throw new Error("bigint: r3=" + r3 + " b0=" + b[0]);
print("ok");

